SELECT id, symbol, interval_code, UNIX_TIMESTAMP(generated_at) AS gen_epoch, decision, original_decision, total_score, confidence_score, data_quality_valid, final_entry_allowed, primary_blocking_stage, confluence_status, confluence_higher_decision, btc_context_status, liquidity_status, derivatives_status, RIGHT(explanation, 900) AS expl_tail FROM crypto_ai.trade_signal WHERE id IN (156721,155320,176655,175258,171559,164516,165289,167616,167617,159285,159407) ORDER BY id;